const {test,assert,path,root,vue,loader,mount,tick,clone,deferred,ticket,all,text,pageFile}=require('./helpers/diy-list-runtime.cjs');
const editor=path.join(root,'components/content/DiyCombinationEditor.vue'),preview=path.join(root,'components/content/DiyCombinationPreview.vue'),util=path.join(root,'utils/diyCombinationEditor.ts');
const fresh=(time=10)=>loader().load(util).newCombinationBlock(time);
const product=(id=17,extra={})=>({id,product_id:id+1000,title:'当前拼团商品'+id,people:3,pink_count:9,image:'/products/'+id+'.png',price:'7.00',ot_price:'12.00',sales:9,stock:99,...extra});
const response=(data,status=200)=>({ok:status===200,status,json:async()=>({status:status===200?200:400000,msg:'拼团商品读取失败',data})});
function harness(value=[fresh()],options={}){const l=loader(options),props=vue.reactive({modelValue:JSON.stringify(value),editorKey:'combination:2',pageId:2,disabled:false,...options.props}),writes=[],m=mount(l,editor,props,(_n,raw)=>{writes.push(raw);props.modelValue=raw;});return{...l,...m,props,writes,value:()=>JSON.parse(props.modelValue)};}
function control(r,label){const f=all(r.tree,n=>n.props['data-element']==='el-form-item'&&n.props['data-label']===label)[0];assert.ok(f,label);const c=all(f,n=>['el-select','el-input','el-input-number','el-switch'].includes(n.props['data-element'])&&n.props['onUpdate:modelValue'])[0];assert.ok(c,label);return c;}
async function update(r,label,value){control(r,label).props['onUpdate:modelValue'](value);await tick();}
async function fetches(send,work){const previous=global.fetch;global.fetch=send;try{await work();}finally{global.fetch=previous;}}
function button(r,label){const n=all(r.tree,n=>n.props['data-element']==='el-button'&&text(n).trim()===label)[0];assert.ok(n,label);return n;}

